from django.contrib.admin.options import IncorrectLookupParameters
from django.contrib.admin.views.main import ChangeList, SEARCH_VAR
from django.core.paginator import InvalidPage


class PowerChangeList(ChangeList):

    def __init__(self, request, model, list_display, list_display_links,
                 list_filter, date_hierarchy, search_fields, list_select_related,
                 list_per_page, list_max_show_all, list_editable, model_admin, *args, **kwargs):
        self.date_hierarchy__lte = f'{date_hierarchy}__lte' if date_hierarchy else None
        self.date_hierarchy__gte = f'{date_hierarchy}__gte' if date_hierarchy else None
        self.multi_search_fields = model_admin.get_multi_search_fields(request)
        # Filtros preservados com os parâmetros multi_search
        self.original_prepreserved_filters = model_admin.get_preserved_filters(request)
        # Criando o multi_search_query
        self.multi_search_query = {}
        request.GET._mutable = True
        for k, l, f in model_admin.multi_search:
            if k in request.GET:
                self.multi_search_query[k] = request.GET.get(k, '')
                del request.GET[k]
        request.GET._mutable = False

        super(PowerChangeList, self).__init__(request, model, list_display, list_display_links,
                                              list_filter, date_hierarchy, search_fields, list_select_related,
                                              list_per_page, list_max_show_all, list_editable, model_admin, *args,
                                              **kwargs)
        # Adiciona os parâmetros do multi_search para construir corretamente a lista de filtros e substitui
        # o preserved_filters sem multi_search pelo original_prepreserved_filters
        self.params.update(self.multi_search_query)
        self.preserved_filters = self.original_prepreserved_filters

    def get_results(self, request):
        paginator = self.model_admin.get_paginator(request, self.queryset, self.list_per_page)
        # Get the number of objects, with admin filters applied.
        result_count = paginator.count

        # Get the total number of objects, with no admin filters applied.
        # Perform a slight optimization:
        # full_result_count is equal to paginator.count if no filters
        # were applied
        if self.get_filters_params() or self.params.get(SEARCH_VAR) or self.multi_search_query:
            full_result_count = self.root_queryset.count()
        else:
            full_result_count = result_count
        can_show_all = result_count <= self.list_max_show_all
        multi_page = result_count > self.list_per_page

        # Get the list of objects to display on this page.
        if (self.show_all and can_show_all) or not multi_page:
            result_list = self.queryset._clone()
        else:
            try:
                result_list = paginator.page(self.page_num).object_list
            except InvalidPage:
                raise IncorrectLookupParameters

        self.result_count = result_count
        self.full_result_count = full_result_count
        self.result_list = result_list
        self.can_show_all = can_show_all
        self.multi_page = multi_page
        self.paginator = paginator
        self.show_full_result_count = self.model_admin.show_full_result_count
        # Admin actions are shown if there is at least one entry
        # or if entries are not counted because show_full_result_count is disabled
        self.show_admin_actions = not self.show_full_result_count or bool(full_result_count)

    def get_queryset(self, request):
        # Atribui em self.query, assim não preciso sobrescrever o método get_queryset do changelist inteiro.
        # A classe do model admin vai identificar quando usar a busca padrão ou multi_search pelo tipo passado em
        # self.query
        if self.multi_search_query:
            self.query = self.multi_search_query

        return super().get_queryset(request)

    def get_filters_params(self, params=None):
        lookup_params = super().get_filters_params(params)
        # Remove os parâmetros multi_search (q1, q2, q3, etc) para poder executar os actions
        for ignored in self.multi_search_query.keys():
            if ignored in lookup_params:
                del lookup_params[ignored]

        return lookup_params
